contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory tos, uint v) public payable {
        bool reverted;
        bool ok;
        if (tos.length == 0) {
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
                ok = false;
            }
        } else {
            // nonempty: low-level call always succeeds at EVM level, so transfer returns true
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                reverted = false;
                ok = r;
            } catch {
                reverted = true;
                ok = false;
            }
        }
        if (tos.length == 0) {
            assert(reverted);
        } else {
            assert(!reverted && ok);
        }
    }
    receive() external payable {}
}

